#!/bin/bash\n# Development environment script for Video Chapter Automater\n# Provides easy access to containerized development workflows\n\nset -euo pipefail\n\n# Configuration\nIMAGE_NAME=\"video-chapter-automater:latest\"\nCONTAINER_NAME=\"vca-dev\"\nDATA_DIR=\"./data\"\nOUTPUT_DIR=\"./output\"\nLOGS_DIR=\"./logs\"\n\n# Colors for output\nRED='\\033[0;31m'\nGREEN='\\033[0;32m'\nYELLOW='\\033[1;33m'\nBLUE='\\033[0;34m'\nNC='\\033[0m' # No Color\n\n# Logging functions\nlog_info() { echo -e \"${BLUE}[INFO]${NC} $1\"; }\nlog_warn() { echo -e \"${YELLOW}[WARN]${NC} $1\"; }\nlog_error() { echo -e \"${RED}[ERROR]${NC} $1\"; }\nlog_success() { echo -e \"${GREEN}[SUCCESS]${NC} $1\"; }\n\n# Help function\nshow_help() {\n    cat << EOF\nUsage: $0 COMMAND [OPTIONS]\n\nDevelopment environment management for Video Chapter Automater.\n\nCOMMANDS:\n    build           Build development Docker image\n    start           Start development container\n    stop            Stop development container\n    restart         Restart development container\n    shell           Open interactive shell in container\n    logs            Show container logs\n    test            Run test suite in container\n    gpu-test        Test GPU capabilities\n    clean           Remove container and clean up\n    status          Show container status\n    process         Process a video file\n    setup           Set up directories and build image\n\nOPTIONS:\n    --gpu           Enable GPU support (default: auto-detect)\n    --cpu           Force CPU-only mode\n    --rebuild       Force rebuild of Docker image\n    --volume PATH   Additional volume mount (format: host:container)\n    -f, --file FILE Video file to process\n    -h, --help      Show this help message\n\nEXAMPLES:\n    # Initial setup\n    $0 setup\n\n    # Start development environment\n    $0 start --gpu\n\n    # Process a video file\n    $0 process --file ./data/video.mp4\n\n    # Open development shell\n    $0 shell\n\n    # Run tests\n    $0 test\n\n    # Clean up everything\n    $0 clean\nEOF\n}\n\n# Check if Docker is available\ncheck_docker() {\n    if ! command -v docker &> /dev/null; then\n        log_error \"Docker is not installed or not in PATH\"\n        exit 1\n    fi\n\n    if ! docker info &> /dev/null; then\n        log_error \"Docker daemon is not running or not accessible\"\n        exit 1\n    fi\n}\n\n# Check GPU availability\ncheck_gpu() {\n    if command -v nvidia-smi &> /dev/null && nvidia-smi &> /dev/null; then\n        return 0\n    else\n        return 1\n    fi\n}\n\n# Setup directories\nsetup_directories() {\n    log_info \"Creating development directories...\"\n    mkdir -p \"$DATA_DIR\" \"$OUTPUT_DIR\" \"$LOGS_DIR\"\n    \n    # Create sample data directory structure\n    mkdir -p \"$DATA_DIR/videos\" \"$DATA_DIR/samples\"\n    \n    # Create .gitkeep files to track empty directories\n    touch \"$DATA_DIR/.gitkeep\" \"$OUTPUT_DIR/.gitkeep\" \"$LOGS_DIR/.gitkeep\"\n    \n    log_success \"Development directories created\"\n}\n\n# Build development image\nbuild_image() {\n    local rebuild=${1:-false}\n    \n    log_info \"Building development Docker image...\"\n    \n    local build_cmd=\"docker build --target development --tag $IMAGE_NAME\"\n    \n    if [[ \"$rebuild\" == \"true\" ]]; then\n        build_cmd=\"$build_cmd --no-cache\"\n    fi\n    \n    if eval \"$build_cmd .\"; then\n        log_success \"Development image built successfully\"\n    else\n        log_error \"Failed to build development image\"\n        exit 1\n    fi\n}\n\n# Start development container\nstart_container() {\n    local gpu_support=${1:-auto}\n    local extra_volumes=${2:-\"\"}\n    \n    # Check if container is already running\n    if docker ps -q -f name=\"$CONTAINER_NAME\" | grep -q .; then\n        log_warn \"Container $CONTAINER_NAME is already running\"\n        return 0\n    fi\n    \n    # Remove existing stopped container\n    if docker ps -aq -f name=\"$CONTAINER_NAME\" | grep -q .; then\n        log_info \"Removing existing container...\"\n        docker rm \"$CONTAINER_NAME\"\n    fi\n    \n    local docker_cmd=\"docker run -d --name $CONTAINER_NAME\"\n    \n    # GPU support\n    if [[ \"$gpu_support\" == \"gpu\" ]] || [[ \"$gpu_support\" == \"auto\" && $(check_gpu) ]]; then\n        docker_cmd=\"$docker_cmd --gpus all\"\n        log_info \"GPU support enabled\"\n    else\n        docker_cmd=\"$docker_cmd -e FORCE_CPU=true\"\n        log_info \"CPU-only mode enabled\"\n    fi\n    \n    # Volume mounts\n    docker_cmd=\"$docker_cmd -v $(pwd):/app\"\n    docker_cmd=\"$docker_cmd -v $(pwd)/$DATA_DIR:/data\"\n    docker_cmd=\"$docker_cmd -v $(pwd)/$OUTPUT_DIR:/output\"\n    docker_cmd=\"$docker_cmd -v $(pwd)/$LOGS_DIR:/app/logs\"\n    \n    # Add extra volumes if specified\n    if [[ -n \"$extra_volumes\" ]]; then\n        for volume in $extra_volumes; do\n            docker_cmd=\"$docker_cmd -v $volume\"\n        done\n    fi\n    \n    # Environment variables\n    docker_cmd=\"$docker_cmd -e PYTHONUNBUFFERED=1\"\n    docker_cmd=\"$docker_cmd -e DEVELOPMENT_MODE=true\"\n    \n    # Keep container running\n    docker_cmd=\"$docker_cmd -t $IMAGE_NAME tail -f /dev/null\"\n    \n    log_info \"Starting development container...\"\n    if eval \"$docker_cmd\"; then\n        log_success \"Development container started: $CONTAINER_NAME\"\n    else\n        log_error \"Failed to start development container\"\n        exit 1\n    fi\n}\n\n# Stop development container\nstop_container() {\n    if docker ps -q -f name=\"$CONTAINER_NAME\" | grep -q .; then\n        log_info \"Stopping development container...\"\n        docker stop \"$CONTAINER_NAME\"\n        log_success \"Container stopped\"\n    else\n        log_warn \"Container $CONTAINER_NAME is not running\"\n    fi\n}\n\n# Open shell in container\nopen_shell() {\n    if ! docker ps -q -f name=\"$CONTAINER_NAME\" | grep -q .; then\n        log_error \"Container $CONTAINER_NAME is not running\"\n        log_info \"Start the container first: $0 start\"\n        exit 1\n    fi\n    \n    log_info \"Opening shell in development container...\"\n    docker exec -it \"$CONTAINER_NAME\" /bin/bash\n}\n\n# Show container logs\nshow_logs() {\n    if ! docker ps -aq -f name=\"$CONTAINER_NAME\" | grep -q .; then\n        log_error \"Container $CONTAINER_NAME does not exist\"\n        exit 1\n    fi\n    \n    docker logs -f \"$CONTAINER_NAME\"\n}\n\n# Run tests in container\nrun_tests() {\n    if ! docker ps -q -f name=\"$CONTAINER_NAME\" | grep -q .; then\n        log_error \"Container $CONTAINER_NAME is not running\"\n        log_info \"Start the container first: $0 start\"\n        exit 1\n    fi\n    \n    log_info \"Running test suite...\"\n    docker exec \"$CONTAINER_NAME\" pytest -v\n}\n\n# Test GPU capabilities\ntest_gpu() {\n    if ! docker ps -q -f name=\"$CONTAINER_NAME\" | grep -q .; then\n        log_error \"Container $CONTAINER_NAME is not running\"\n        log_info \"Start the container first: $0 start\"\n        exit 1\n    fi\n    \n    log_info \"Testing GPU capabilities...\"\n    docker exec \"$CONTAINER_NAME\" python test_gpu.py\n}\n\n# Process video file\nprocess_video() {\n    local video_file=${1:-\"\"}\n    \n    if [[ -z \"$video_file\" ]]; then\n        log_error \"No video file specified\"\n        log_info \"Usage: $0 process --file /path/to/video.mp4\"\n        exit 1\n    fi\n    \n    if [[ ! -f \"$video_file\" ]]; then\n        log_error \"Video file not found: $video_file\"\n        exit 1\n    fi\n    \n    if ! docker ps -q -f name=\"$CONTAINER_NAME\" | grep -q .; then\n        log_error \"Container $CONTAINER_NAME is not running\"\n        log_info \"Start the container first: $0 start\"\n        exit 1\n    fi\n    \n    log_info \"Processing video: $video_file\"\n    docker exec \"$CONTAINER_NAME\" python -m video_chapter_automater.cli \"$video_file\"\n}\n\n# Clean up everything\nclean_up() {\n    log_info \"Cleaning up development environment...\"\n    \n    # Stop and remove container\n    if docker ps -q -f name=\"$CONTAINER_NAME\" | grep -q .; then\n        docker stop \"$CONTAINER_NAME\"\n    fi\n    \n    if docker ps -aq -f name=\"$CONTAINER_NAME\" | grep -q .; then\n        docker rm \"$CONTAINER_NAME\"\n    fi\n    \n    # Optionally remove image\n    read -p \"Remove Docker image as well? [y/N]: \" -n 1 -r\n    echo\n    if [[ $REPLY =~ ^[Yy]$ ]]; then\n        docker rmi \"$IMAGE_NAME\" || true\n    fi\n    \n    log_success \"Cleanup completed\"\n}\n\n# Show container status\nshow_status() {\n    echo \"Development Environment Status:\"\n    echo \"==============================\"\n    \n    if docker ps -q -f name=\"$CONTAINER_NAME\" | grep -q .; then\n        echo \"🟢 Container: $CONTAINER_NAME (RUNNING)\"\n    elif docker ps -aq -f name=\"$CONTAINER_NAME\" | grep -q .; then\n        echo \"🟡 Container: $CONTAINER_NAME (STOPPED)\"\n    else\n        echo \"🔴 Container: $CONTAINER_NAME (NOT CREATED)\"\n    fi\n    \n    if docker images -q \"$IMAGE_NAME\" | grep -q .; then\n        echo \"🟢 Image: $IMAGE_NAME (BUILT)\"\n    else\n        echo \"🔴 Image: $IMAGE_NAME (NOT BUILT)\"\n    fi\n    \n    echo \"📁 Data Directory: $DATA_DIR $([ -d \"$DATA_DIR\" ] && echo \"(EXISTS)\" || echo \"(MISSING)\")\"\n    echo \"📁 Output Directory: $OUTPUT_DIR $([ -d \"$OUTPUT_DIR\" ] && echo \"(EXISTS)\" || echo \"(MISSING)\")\"\n    echo \"📁 Logs Directory: $LOGS_DIR $([ -d \"$LOGS_DIR\" ] && echo \"(EXISTS)\" || echo \"(MISSING)\")\"\n    \n    if check_gpu; then\n        echo \"🚀 GPU: Available\"\n    else\n        echo \"💻 GPU: Not Available (CPU mode)\"\n    fi\n}\n\n# Setup everything\nsetup_environment() {\n    local rebuild=${1:-false}\n    \n    log_info \"Setting up development environment...\"\n    check_docker\n    setup_directories\n    build_image \"$rebuild\"\n    log_success \"Development environment setup completed\"\n    \n    echo \"\"\n    log_info \"Next steps:\"\n    echo \"  1. Place video files in $DATA_DIR/\"\n    echo \"  2. Start development container: $0 start\"\n    echo \"  3. Open development shell: $0 shell\"\n    echo \"  4. Process videos: $0 process --file ./data/video.mp4\"\n}\n\n# Parse command line arguments\nCOMMAND=\"\"\nGPU_MODE=\"auto\"\nREBUILD=false\nVIDEO_FILE=\"\"\nEXTRA_VOLUMES=\"\"\n\nif [[ $# -eq 0 ]]; then\n    show_help\n    exit 0\nfi\n\nCOMMAND=$1\nshift\n\nwhile [[ $# -gt 0 ]]; do\n    case $1 in\n        --gpu)\n            GPU_MODE=\"gpu\"\n            shift\n            ;;\n        --cpu)\n            GPU_MODE=\"cpu\"\n            shift\n            ;;\n        --rebuild)\n            REBUILD=true\n            shift\n            ;;\n        --volume)\n            EXTRA_VOLUMES=\"$EXTRA_VOLUMES $2\"\n            shift 2\n            ;;\n        -f|--file)\n            VIDEO_FILE=\"$2\"\n            shift 2\n            ;;\n        -h|--help)\n            show_help\n            exit 0\n            ;;\n        *)\n            log_error \"Unknown option: $1\"\n            show_help\n            exit 1\n            ;;\n    esac\ndone\n\n# Execute command\ncheck_docker\n\ncase $COMMAND in\n    build)\n        build_image \"$REBUILD\"\n        ;;\n    start)\n        start_container \"$GPU_MODE\" \"$EXTRA_VOLUMES\"\n        ;;\n    stop)\n        stop_container\n        ;;\n    restart)\n        stop_container\n        sleep 2\n        start_container \"$GPU_MODE\" \"$EXTRA_VOLUMES\"\n        ;;\n    shell)\n        open_shell\n        ;;\n    logs)\n        show_logs\n        ;;\n    test)\n        run_tests\n        ;;\n    gpu-test)\n        test_gpu\n        ;;\n    clean)\n        clean_up\n        ;;\n    status)\n        show_status\n        ;;\n    process)\n        process_video \"$VIDEO_FILE\"\n        ;;\n    setup)\n        setup_environment \"$REBUILD\"\n        ;;\n    *)\n        log_error \"Unknown command: $COMMAND\"\n        show_help\n        exit 1\n        ;;\nesac